import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA kernel (fp16 input & weight, fp16 output, fp32 accumulation)
# ----------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void conv1d_fp16_kernel(const half* __restrict__ input,
                                   const half* __restrict__ weight,
                                   half* __restrict__ output,
                                   int batch,
                                   int in_c,
                                   int out_c,
                                   int length,
                                   int kernel_size,
                                   int length_out) {
    int out_pos = blockIdx.x * blockDim.x + threadIdx.x;
    if (out_pos >= length_out) return;

    int n = blockIdx.y;                     // flattened (batch, out_c)
    int batch_idx = n / out_c;
    int out_ch = n % out_c;

    float acc = 0.0f;
    for (int ic = 0; ic < in_c; ++ic) {
        int input_base  = ((batch_idx * in_c + ic) * length) + out_pos;
        int weight_base = ((out_ch * in_c + ic) * kernel_size);
        #pragma unroll
        for (int k = 0; k < kernel_size; ++k) {
            half h_in = input[input_base + k];
            half h_w  = weight[weight_base + k];
            acc += __half2float(h_in) * __half2float(h_w);
        }
    }
    output[((batch_idx * out_c + out_ch) * length_out) + out_pos] = __float2half(acc);
}

void conv1d_fp16(torch::Tensor input,
                 torch::Tensor weight,
                 torch::Tensor output) {
    const int batch       = input.size(0);
    const int in_c        = input.size(1);
    const int length      = input.size(2);
    const int out_c       = weight.size(0);
    const int kernel_size = weight.size(2);
    const int length_out  = length - kernel_size + 1;

    const dim3 block(256);
    const dim3 grid((length_out + block.x - 1) / block.x,
                    batch * out_c);

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "conv1d_fp16_kernel", ([&] {
        conv1d_fp16_kernel<<<grid, block>>>(
            input.data_ptr<half>(),
            weight.data_ptr<half>(),
            output.data_ptr<half>(),
            batch,
            in_c,
            out_c,
            length,
            kernel_size,
            length_out);
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA error in conv1d_fp16: %s\\n", cudaGetErrorString(err));
    }
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv1d_fp16", &conv1d_fp16, "1D convolution (fp16, CUDA)");
}
'''

# Compile the extension
conv1d_ext = load_inline(name='conv1d_fp16_ext',
                         cpp_sources='',
                         cuda_sources=cuda_source,
                         functions=['conv1d_fp16'],
                         verbose=False)

# ----------------------------------------------------------------------
# Python wrapper around the custom kernel
# ----------------------------------------------------------------------
def _conv1d_fp16(input: torch.Tensor, weight: torch.Tensor) -> torch.Tensor:
    """
    input : (B, C_in, L)   fp16, contiguous
    weight: (C_out, C_in, K) fp16, contiguous
    returns: (B, C_out, L_out) fp16
    """
    if not input.is_contiguous():
        input = input.contiguous()
    if not weight.is_contiguous():
        weight = weight.contiguous()

    B, C_in, L = input.shape
    C_out, _, K = weight.shape
    L_out = L - K + 1

    output = torch.empty((B, C_out, L_out), dtype=torch.float16,
                         device=input.device)
    conv1d_ext.conv1d_fp16(input, weight, output)
    return output

# ----------------------------------------------------------------------
# Model definition using the custom kernel
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model, using a hand‑written
    fp16 CUDA kernel for the 1‑D convolution.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size

        # weight shape: (out_channels, in_channels, kernel_size)
        weight = torch.empty(out_channels, in_channels, kernel_size,
                             dtype=torch.float16)
        # Kaiming uniform (same as nn.Conv1d default)
        nn.init.kaiming_uniform_(weight, a=math.sqrt(5))
        self.weight = nn.Parameter(weight)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure fp16
        if x.dtype != torch.float16:
            x = x.to(torch.float16)
        return _conv1d_fp16(x, self.weight)
